from collections import defaultdict

class Room:
    def __init__(self, name):
        self.name = name
        self.connections = {
            "төньяк": None,
            "көньяк": None,
            "көнчыгыш": None,
            "көнбатыш": None
        }
        self.visited = False

    def connect(self, direction, room):
        self.connections[direction] = room

    def get_available_directions(self):
        return [dir for dir, room in self.connections.items() if room is not None]

    def get_unvisited_neighbors(self):
        return [dir for dir, room in self.connections.items() if room is not None and not room.visited]

class House:
    def __init__(self):
        self.rooms = {}
        self.current_room = None

    def add_room(self, room_name):
        if room_name not in self.rooms:
            self.rooms[room_name] = Room(room_name)

    def connect_rooms(self, room1_name, room2_name, direction1, direction2):
        room1 = self.rooms[room1_name]
        room2 = self.rooms[room2_name]
        room1.connect(direction1, room2)
        room2.connect(direction2, room1)

    def set_start_room(self, room_name):
        self.current_room = self.rooms[room_name]
        self.current_room.visited = True

    def move(self, direction):
        if direction in self.current_room.connections and self.current_room.connections[direction] is not None:
            self.current_room = self.current_room.connections[direction]
            self.current_room.visited = True
            return True
        return False

    def is_finished(self):
        return all(room.visited for room in self.rooms.values())

    def get_available_directions(self):
        return self.current_room.get_available_directions()

    def get_unvisited_neighbors(self):
        return self.current_room.get_unvisited_neighbors()

